import { existsSync } from 'node:fs';

import { expect, test } from '../../fixtures/index.ts';
import { shellReady } from '../shell/helpers.ts';

// `@visual` baselines for proof of value (#86): the privacy card and the context test, in the
// 360/768/1280 light and dark projects. Baselines are only generated by the e2e workflow's
// `update_snapshots` dispatch (see e2e/README.md); until they exist each test skips.
for (const name of ['privacy-card', 'context-test'] as const) {
  test(`proof-of-value ${name}`, { tag: '@visual' }, async ({ page, asUser }, testInfo) => {
    const baseline = testInfo.snapshotPath(`proof-of-value-${name}.png`, { kind: 'screenshot' });
    test.skip(
      testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
      'no baseline yet: dispatch the e2e workflow with update_snapshots',
    );
    await asUser('owner', { path: 'settings/privacy' });
    await shellReady(page);
    const slot =
      name === 'privacy-card' ? '[data-slot="pov-card"]' : '[data-slot="context-test-flow"]';
    await expect(page.locator(slot)).toHaveScreenshot(`proof-of-value-${name}.png`);
  });
}
